using System;using System.Collections;using System.Collections.Generic;using System.IO;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
public sealed partial class FlightMeasurementPlayMode {
 [UnityTest]public IEnumerator R15FloorTurn(){Directory.CreateDirectory(Evidence);var report=new R14Report{revision="r15-rotating-support-risk3",method="Saved16deg real support penetration/COM-up gating cause. Natural601charge ticks,Tick1/60. Same layout/material/stock/safety threshold; actual breaks separate from boost count."};string file=Path.Combine(Evidence,"floor-turn.json");Assert.That(File.Exists(file),Is.False);Action save=()=>File.WriteAllText(file,JsonUtility.ToJson(report,true));save();var failed=new List<string>();
 foreach(var spec in new[]{new R12Spec{id="r15-neighbor16",angle=16,level=0,rate=2},new R12Spec{id="r15-standard12",angle=12,level=0,rate=2},new R12Spec{id="r15-strong35",angle=35}}){yield return NewRetrySubject(false,true,true,true,true,true,true);StartRouteChargeR11(spec.angle,spec.level,spec.rate,spec.direction);var sim=Property(current,"ReviewSimulation");var row=new R14Trial{id=spec.id,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.trials.Add(row);bool before=false,after=false;
 for(int tick=0;tick<11000&&!(bool)Property(current,"Finished");tick++){Call(current,"Tick",1f/60);var s=State(current);float dist=F(s,"distance");if(!before&&dist>953){CaptureRoute(spec.id,"floor-approach");before=true;}if(!after&&F(s,"time")>19.31f){CaptureRoute(spec.id,"after-window");after=true;}}
 row.final=JsonUtility.ToJson(State(current));foreach(var e in (IEnumerable)Field(sim,"BreakEvents"))row.actualBreaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});row.contactTrace=(string)Call(sim,"ReviewContactTraceJson");CaptureRoute(spec.id,"result");save();if(!(bool)Property(current,"Finished")||!String.IsNullOrEmpty((string)Field(State(current),"physicsFault")))failed.Add(spec.id+":"+(string)Field(State(current),"physicsFault"));Call(current,"RetryLaunch","");Assert.That(Convert.ToInt32(Field(State(current),"destructionEvent")),Is.EqualTo(0));Assert.That(Convert.ToInt32(Field(State(current),"rechargeCount")),Is.EqualTo(0));Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state=failed.Count==0?"COMPLETED_NO_OBSERVED_FAULT":"COMPLETED_WITH_OBSERVED_FAULT";save();Assert.That(failed,Is.Empty,String.Join(",",failed));}
}
